mapper.select:
SELECT DISTINCT sdi.id AS id, sdi.dataset_id AS datasetId, sdi.name AS name, MAX(sif.scene_type) AS sceneType, MAX(sif.haze_level) AS hazeLevel, sdi.create_time AS createTime,
MAX(CASE WHEN sf.name = #{keywords} THEN 100 WHEN sf.name LIKE CONCAT('%', #{keywords}, '%') THEN 50 ELSE 0 END + CASE WHEN sif.description LIKE CONCAT('%', #{keywords}, '%') THEN 30 ELSE 0 END + CASE WHEN sif.scene_type = #{keywords} THEN 20 ELSE 0 END) AS relevance
0 AS relevance
FROM sys_dataset_item sdi LEFT JOIN sys_item_file sif ON sdi.id = sif.item_id LEFT JOIN sys_file sf ON sif.file_id = sf.id WHERE sdi.dataset_id IN
#{leafId}
AND (sf.name LIKE CONCAT('%', #{keywords}, '%') OR sif.description LIKE CONCAT('%', #{keywords}, '%') OR sif.scene_type LIKE CONCAT('%', #{keywords}, '%'))
AND sif.scene_type = #{sceneType}
AND sif.haze_level = #{hazeLevel}
AND sif.width >= #{minWidth}
AND sif.width <= #{maxWidth}
AND sif.height >= #{minHeight}
AND sif.height <= #{maxHeight}
AND CAST(REPLACE(REPLACE(sf.size, ' ', ''), 'B', '') AS UNSIGNED) >= #{minSize}
AND CAST(REPLACE(REPLACE(sf.size, ' ', ''), 'B', '') AS UNSIGNED) <= #{maxSize}
GROUP BY sdi.id, sdi.dataset_id, sdi.name, sdi.create_time
ORDER BY relevance DESC, sdi.create_time DESC
ORDER BY sdi.create_time DESC
